<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
import { Camera, CircleCheck, Close, Refresh } from '@element-plus/icons-vue'
import { api, post, remove, errorText } from '../api'
import { useCamera } from '../composables'
import { FrameBudget, maskedIdentity } from '../cameraProtocol.mjs'
const {video,cameraError,cameraReady,start:cameraStart,stop:cameraStop,frame}=useCamera()
const status=ref<any>(null),statusError=ref(''),busy=ref(false),prompt=ref('选择打卡类型，准备开始今天的记录。'),result=ref<{success:boolean;message:string;employeeName?:string;employeeNo?:string}|null>(null),clock=ref(''),punchType=ref<'IN'|'OUT'>('IN')
const statusLoading=ref(false)
const canStart=computed(()=>!statusLoading.value&&status.value?.authorized===true&&status.value?.ready===true)
let ws:WebSocket|null=null,sessionId='',captureTimer:ReturnType<typeof setInterval>|undefined,timeoutTimer:ReturnType<typeof setTimeout>|undefined,resultTimer:ReturnType<typeof setTimeout>|undefined,clockTimer:ReturnType<typeof setInterval>|undefined,inFlight=false,completed=false,epoch=0,resolving=false
function clearCapture(){if(captureTimer)clearInterval(captureTimer);if(timeoutTimer)clearTimeout(timeoutTimer);captureTimer=undefined;timeoutTimer=undefined;if(ws){ws.onclose=null;ws.onerror=null;ws.onmessage=null;ws.onopen=null;ws.close();ws=null}cameraStop();busy.value=false}
async function checkStatus(){statusLoading.value=true;statusError.value='';try{status.value=await api('/kiosk/status');return status.value?.authorized===true&&status.value?.ready===true}catch(e){status.value=null;statusError.value=errorText(e);return false}finally{statusLoading.value=false}}
function showResult(data:any){completed=true;clearCapture();result.value={success:['SUCCESS','DUPLICATE'].includes(data.status),message:data.message||'本次打卡已结束，请核查记录',...maskedIdentity(data.employeeName,data.employeeNo)};prompt.value='本次会话已结束';if(resultTimer)clearTimeout(resultTimer);resultTimer=setTimeout(()=>{result.value=null;prompt.value='选择打卡类型，准备开始今天的记录。'},3000)}
async function cancel(keepBusy=false){epoch++;const id=sessionId;sessionId='';completed=true;clearCapture();busy.value=keepBusy;prompt.value='已停止采集，可以重新开始。';if(id)await remove(`/kiosk/sessions/${encodeURIComponent(id)}`).catch(()=>{})}
async function fail(message:string){const id=sessionId;sessionId='';showResult({type:'ERROR',message});if(id)await remove(`/kiosk/sessions/${encodeURIComponent(id)}`).catch(()=>{})}
async function resolveDisconnected(){if(completed||!sessionId||resolving)return;resolving=true;const id=sessionId,current=epoch;clearCapture();try{const data=await api(`/kiosk/sessions/${encodeURIComponent(id)}`);if(current!==epoch)return;if(data.status==='COMPLETED'||data.status==='SUCCESS'||data.status==='DUPLICATE'){showResult(data);return}}catch{}finally{resolving=false}if(current===epoch)await fail('连接中断，本次结果未确认。请联系管理员核查记录后重新开始。')}
async function begin(type:'IN'|'OUT'){
  if(busy.value||statusLoading.value)return;const cancellation=cancel(true),current=epoch;await cancellation;if(current!==epoch)return;if(resultTimer)clearTimeout(resultTimer);result.value=null;punchType.value=type;prompt.value='正在检查设备与识别服务…'
  try{
    const ready=await checkStatus();if(current!==epoch)return;if(!ready){busy.value=false;prompt.value=status.value?.message||statusError.value||'打卡条件未满足，请联系管理员处理后刷新状态。';return}
    prompt.value='正在打开摄像头…'
    if(!await cameraStart()){busy.value=false;return};if(current!==epoch)return
    const data=await post('/kiosk/sessions',{type});if(current!==epoch){await remove(`/kiosk/sessions/${data.sessionId}`).catch(()=>{});return}
    sessionId=data.sessionId;completed=false;prompt.value=data.livenessRequired?'请单人正对镜头，保持自然睁眼、闭嘴，按提示完成动作。':'请单人正对镜头，保持面部清晰。'
    ws=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/api/v1/kiosk/stream?sessionId=${encodeURIComponent(sessionId)}`);ws.binaryType='arraybuffer'
    timeoutTimer=setTimeout(()=>{if(current===epoch&&!completed)fail('无法建立识别连接，请检查网络后重试。')},8000)
    ws.onopen=()=>{if(timeoutTimer)clearTimeout(timeoutTimer);const budget=new FrameBudget(performance.now());timeoutTimer=setTimeout(()=>fail('验证超时，请调整光线和位置后重试。'),12000);captureTimer=setInterval(async()=>{if(inFlight||!ws||ws.readyState!==WebSocket.OPEN||completed||current!==epoch||ws.bufferedAmount>=400*1024)return;inFlight=true;try{const blob=await frame();if(!blob||completed||current!==epoch)return;if(!budget.accept(blob.size,performance.now())){await fail('采集已达到本次上限，请重新开始。');return}if(ws?.readyState===WebSocket.OPEN)ws.send(blob)}catch(e){if(current===epoch&&!completed)await fail(errorText(e))}finally{inFlight=false}},167)}
    ws.onmessage=event=>{try{const data=JSON.parse(event.data);if(data.type==='RESULT')showResult(data);else if(data.type==='ERROR')fail(data.message||'本次验证未通过，请重试');else if(data.type==='PROMPT')prompt.value=data.message||({BLINK:'请眨眼，然后恢复自然睁眼',MOUTH:'请张嘴，然后闭嘴'} as any)[data.action]||'请按照提示完成动作'}catch{fail('服务返回了无法识别的消息，请重新开始。')}}
    ws.onerror=()=>{if(!completed)resolveDisconnected()};ws.onclose=()=>{if(!completed)resolveDisconnected()}
  }catch(e){if(current===epoch)await fail(errorText(e))}
}
onMounted(()=>{checkStatus();const tick=()=>clock.value=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'long',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date());tick();clockTimer=setInterval(tick,1000)})
onBeforeUnmount(()=>{cancel();if(resultTimer)clearTimeout(resultTimer);if(clockTimer)clearInterval(clockTimer)})
</script>
<template><div class="kiosk-page"><header class="kiosk-header"><router-link class="brand" to="/"><span class="brand-mark">知</span><div>知行<small>SMART ATTENDANCE</small></div></router-link><router-link to="/login"><el-button text>管理入口 →</el-button></router-link></header><main class="kiosk-body"><div class="eyebrow">A FRESH START, EVERY DAY</div><h1>轻松一刻，完成打卡</h1><div class="kiosk-time">{{clock}} · 北京时间</div><el-alert v-if="statusError" :title="statusError" type="warning" show-icon :closable="false" style="margin-top:20px"/><el-alert v-if="status && status.authorized===false" title="当前浏览器尚未授权。请管理员在本设备登录，在「打卡设备」中授权本浏览器。" type="warning" show-icon :closable="false" style="margin-top:20px"/><el-alert v-if="status?.authorized && !status.ready" :title="status.message||'识别服务或人员库尚未就绪，请联系管理员检查后刷新状态。'" type="warning" show-icon :closable="false" style="margin-top:20px"/><el-alert v-if="cameraError" :title="cameraError" type="error" show-icon :closable="false" style="margin-top:20px"/><div class="camera-shell kiosk-camera"><video ref="video" autoplay muted playsinline aria-label="实时摄像头预览"/><div v-if="!cameraReady" class="camera-placeholder"><el-icon :size="56"><Camera/></el-icon><span>准备好后，选择上班签到或下班签退</span><small>摄像头仅在打卡过程中开启</small></div><div v-if="cameraReady" class="camera-guide"/><div v-if="cameraReady" class="camera-caption">{{punchType==='IN'?'上班签到':'下班签退'}} · 请保持单人入镜</div></div><div class="kiosk-prompt" aria-live="polite">{{prompt}}</div><div v-if="result" class="result-card" :class="{error:!result.success}" role="status"><el-icon :size="27"><CircleCheck v-if="result.success"/><Close v-else/></el-icon><h2 style="margin:12px 0 6px">{{result.message}}</h2><div v-if="result.employeeName">{{result.employeeName}} · {{result.employeeNo}}</div><small>本次结果将在 3 秒后清除</small></div><div class="camera-actions"><template v-if="!busy"><el-button type="primary" size="large" :icon="Camera" :disabled="!canStart" @click="begin('IN')">上班签到</el-button><el-button size="large" :disabled="!canStart" @click="begin('OUT')">下班签退</el-button></template><el-button v-else size="large" @click="cancel()">停止本次采集</el-button></div><div class="help-text">请保持光线均匀，面部无遮挡。遇到识别困难，可联系管理员通过人工补卡留痕处理。<br>原始图像仅用于本次识别，不在浏览器或业务数据库中持久保存。</div><el-button :icon="Refresh" text style="margin-top:18px"  :loading="statusLoading" :disabled="busy" @click="checkStatus">刷新设备状态</el-button></main></div></template>
